// src/api/ScanApi.js
import { get, post } from './HttpClient';

// 명세: POST /scan/start  Body: { paths:[...] } -> {scanId}
export function startScan(paths = []) {
  return post('/scan/start', { paths });
}

// 명세: POST /scan/{scanId}/pause -> {status:"PAUSED"}
export function pauseScan(scanId) {
  return post(`/scan/${scanId}/pause`);
}

// 명세: GET /scan/{scanId}/progress -> {status, percent, scanned, total, currentPath}
export function fetchScanProgress(scanId) {
  return get(`/scan/${scanId}/progress`);
}
